#!/usr/bin/env python3
"""Independent after-whole-workflow finite Base/Compact source/quantity oracle."""
import argparse, collections, hashlib, json, math, re
from pathlib import Path

def require(ok,message):
    if not ok:raise ValueError(message)
def near(a,b,t=1e-6):require(isinstance(a,(int,float)) and not isinstance(a,bool) and math.isfinite(a) and abs(a-b)<=t,f'{a!r} != {b!r}')
def one(a,label):require(len(a)==1,f'one {label}, got {len(a)}');return a[0]
def defs(width):return [{'name':'width','dimension':'length','expression':f'mm({width})'},{'name':'height','dimension':'length','expression':'width / 2'},{'name':'depth','dimension':'length','expression':'width / 5'},{'name':'hole','dimension':'length','expression':'width / 10'},{'name':'corner','dimension':'length','expression':'hole * 0.4'},{'name':'edge','dimension':'length','expression':'width * 0.08'}]
def spec(base,compact,active):return {'version':2,'definitions':defs(base),'configurations':[{'id':'compact','name':'Compact','overrides':[{'name':'width','expression':f'mm({compact})'}]}],'activeId':active}
def derive(source):
    if source.startswith('codi-physical-parameters:1\n'):
        value=json.loads(source.split('\n',1)[1]);require(value==defs(100),'known initial v1 formula source');return 100,None
    require(source.startswith('codi-physical-parameters:2\n'),'actual v2 configuration source');value=json.loads(source.split('\n',1)[1]);require(set(value)=={'version','definitions','configurations','activeId'} and value['version']==2,'exact saved configuration schema');base=one([n for n in (100,120) if value['definitions']==defs(n)],'known Base definitions');config=one(value['configurations'],'one sparse Compact');require(set(config)=={'id','name','overrides'} and config['id']=='compact' and config['name']=='Compact' and len(config['overrides'])==1,'no duplicated geometry or invented Base variant');compact=one([n for n in (80,90) if config['overrides']==[{'name':'width','expression':f'mm({n})'}]],'known Compact width');require(value['activeId'] in (None,'compact'),'Base means null');require(value==spec(base,compact,value['activeId']),'exact finite configuration definitions');return compact if value['activeId']=='compact' else base,value
def dimensions(width):
    h=width/2;d=width/5;r=width/20;s=width/50;e=width*.08
    return {'width':width,'height':h,'depth':d,'hole':2*r,'corner':2*s,'edge':e,'volume':(width*h-math.pi*(r*r+4*s*s))*d}
def point_mapping(receipt):
    initial=one([r for r in receipt['rows'] if r['label']=='Actual public typed Base before configuration registration'],'actual initial source');source=json.loads(initial['before']['capture']['native']['source']);objects={o['id']:o for o in source['objects']};mapping={}
    for p in receipt['sourceInspection']['points']:
        require(p['parentId'] in objects and p['id'] not in mapping,'actual unique public endpoint parent');o=objects[p['parentId']];end=one([k for k in ('a','b') if math.hypot(o['data'][k]['x']-p['x'],o['data'][k]['y']-p['y'])<=1e-9],'real endpoint/data association');mapping[p['id']]=(p['parentId'],end)
    require(len(mapping)==8,'eight actual source endpoints, no ID syntax assumptions');return mapping,list(objects)
def source_equations(source,width,mapping,object_ids):
    require(source['version']==3 and [o['id'] for o in source['objects']]==object_ids and len(source['stages'])==1,'source IDs/order/stage retained');objects={o['id']:o for o in source['objects']};require(all(o['type']=='Segment' and o['stage']==0 and o['role'] is None for o in source['objects']),'ordinary rectangle source');require(source['metadata']['boundaryFrame']=={'origin':[0,0,0],'x':[1,0,0],'y':[0,1,0],'z':[0,0,1]},'canonical physical source frame');corners=collections.Counter()
    for o in source['objects']:
        for p in (o['data']['a'],o['data']['b']):corner=one([q for q in [(0,0),(width,0),(width,width/2),(0,width/2)] if math.hypot(p['x']-q[0],p['y']-q[1])<=1e-6],'independent physical corner');corners[corner]+=1
    require(len(corners)==4 and set(corners.values())=={2},'complete ordinary rectangle boundary');cs=source['stages'][0]['constraints'];require(collections.Counter(c['typeId'] for c in cs)==collections.Counter({'PCoincident':4,'Horizontal':2,'Vertical':2,'LockPoint':1,'SegmentLength':2}),'actual original equations');require(source['stages'][0]['generators']==[],'no solved-copy generator')
    def point(id):require(id in mapping,'actual discovered equation point');parent,end=mapping[id];return objects[parent]['data'][end]
    for c in cs:
        require(c['stage']==0 and c['admission']['version']==1 and c['admission']['state'] in ('accepted','redundant'),'actual admitted original row');t=c['typeId'];refs=c['objects'];constants=c.get('constants',{})
        if t=='PCoincident':
            a,b=[point(id) for id in refs];near(a['x']-b['x'],0);near(a['y']-b['y'],0)
        elif t=='LockPoint':
            p=point(one(refs,'locked point'));near(p['x'],float(constants['x']));near(p['y'],float(constants['y']));near(float(constants['x']),0);near(float(constants['y']),0)
        else:
            o=objects[one(refs,'source Segment')];a,b=o['data']['a'],o['data']['b'];dx,dy=b['x']-a['x'],b['y']-a['y']
            if t=='SegmentLength':require(constants['length'] in ('width','height'),'original named source lengths preserved');near(math.hypot(dx,dy),width if constants['length']=='width' else width/2)
            else:target=math.radians(float(constants['angle']));near(math.atan2(math.sin(math.atan2(dy,dx)-target),math.cos(math.atan2(dy,dx)-target)),0,1e-8)
    return True
def state(snapshot,receipt,mapping,object_ids):
    native=snapshot['capture']['native'];width,model=derive(native['expressions']);e=dimensions(width);source=json.loads(native['source']);source_equations(source,width,mapping,object_ids);history=native['history'];require(history==receipt['originalHistory'],'same exact feature graph and name bindings');require([r['type'] for r in history]==['PLANE','WORKER_SELECTED_PROFILE_EXTRUDE_V2','WORKER_THROUGH_HOLES_V1','WORKER_THROUGH_HOLES_V1'],'same supported feature family');profile,center,corners=[row['params'] for row in history[1:]];b=receipt['binding'];require(profile['featureId']==b['profile']['featureId'] and profile['faceId']==b['faceId'] and profile['regionId']==b['regionId'] and profile['depth']=='depth','actual source/opaque region and saved depth name')
    for p,record,producer,kind in [(center,b['center'],b['profile'],'centered-through'),(corners,b['corners'],b['center'],'four-corner-through')]:require(p['featureId']==record['featureId'] and p['target']==producer['outputId'] and p['producerFeatureId']==producer['featureId'] and p['kind']==kind and p['sourceFeatureId']==profile['featureId'] and p['sourceFaceId']==profile['faceId'] and p['sourceRegionId']==profile['regionId'],'unchanged genuine hole source/producer chain')
    require(center['diameter']=='hole' and corners['diameter']=='corner' and corners['offsetX']==corners['offsetY']=='edge','authored formula bindings retained');require(all(p['engine']=='occ' and p['engineRevision']==receipt['engineRevision'] for p in (profile,center,corners)),'one explicit whole-part build')
    p=snapshot['physical'];require(p['ready'] and p['unit']=='millimeter' and p['definitions']==(model['definitions'] if model else defs(100)) and p['configurations']==(model['configurations'] if model else []) and p['activeConfigurationId']==(model['activeId'] if model else None),'public raw Base/configuration/selection truth');require(len(p['quantities'])==6 and {q['name'] for q in p['quantities']}==set(defs_name['name'] for defs_name in defs(100)),'effective quantity census')
    for q in p['quantities']:require(q['dimension']=='length' and q['unit']=='millimeter','actual quantity dimension/unit');near(q['value'],e[q['name']])
    body=one(snapshot['capture']['solids']['bodies'],'current complete output');m=body['metrics'];require(body['id']==b['corners']['outputId'] and body['featureId']==b['corners']['featureId'] and m['nativeValidity']['valid'] and m['resultKind']=='single-solid' and m['solidCount']==1,'genuine same valid Native result');require('sha256:'+m['runtime']['jsSha256']+':'+m['runtime']['wasmSha256']==receipt['engineRevision'],'actual Native runtime');near(m['nativeVolume'],e['volume'])
    for axis in range(3):near(m['nativeBounds']['min'][axis],0);near(m['nativeBounds']['max'][axis],[width,e['height'],e['depth']][axis])
    owner=snapshot['ownership'];require(not owner['processing'] and not owner['resources']['cleanupFailed'] and all(owner['resources'][k]==0 for k in ('candidates','accepted','mounts')),'settled observation/Native resources');return width,model,e
def normalized(s):
    s=json.loads(json.dumps(s))
    for row in (s['host'],s['physical'],s['capture']['journal'],s['capture']['solids'],s['manufacturing']):row.pop('revision',None)
    return s
def material(m,receipt):
    require(m['version']==1 and m['unit']=='millimeter' and re.fullmatch(r'sha256-[a-f0-9]{64}',m['revision']),'actual reviewed manufacturing revision');require(m['materials']==[{'id':'pla','name':'PLA'}] and m['appearances']==[{'id':'blue','name':'Blue','color':'#3366ff'}],'same actual material/color IDs');b=one(m['bindings'],'saved producer binding');require(b['featureId']==receipt['binding']['corners']['featureId'] and b['operationType']=='WORKER_THROUGH_HOLES_V1','actual final producer');part=one(m['objects'],'part');region=one(part['regions'],'region');require(part['id']=='plate' and part['name']=='Configurable mounting plate' and region['id']=='main' and region['bodyId']==b['id'] and region['materialId']=='pla' and region['appearanceId']=='blue','stable part/region/binding identity');return {k:v for k,v in m.items() if k!='revision'}
def main():
    parser=argparse.ArgumentParser();parser.add_argument('evidence',type=Path);args=parser.parse_args();folder=args.evidence;r=json.loads((folder/'receipt.json').read_text());require(r['status']=='PASS' and r['ownedContextClosed'] and r['sharedBrowserDisconnectedOnly'],'completed whole workflow/cleanup');require(r['sourcePins']==r['sourcePinsAfter'] and not r['sourceSeeds'] and not r['privateAuthoring'] and not r['fakeSuccessfulReplies'],'frozen genuine authoring source');require([v for k,v in r['sourcePins'].items() if k.endswith('/compact-configuration-workflow/check.py')]==[hashlib.sha256(Path(__file__).read_bytes()).hexdigest()],'executing independent checker pin');mapping,object_ids=point_mapping(r);observations=[]
    for row in r['rows']:
        if row.get('kind')=='native-observation':
            width,model,e=state(row['before'],r,mapping,object_ids);require(width==row['width'] and model==row['spec'] and row['after']==row['before'],'actual selected source/read-only state truth');z=e['depth']/2;edge=e['edge'];points=[[width/2,e['height']/2,z],[edge,edge,z],[width-edge,edge,z],[width-edge,e['height']-edge,z],[edge,e['height']-edge,z],[width*.3,e['height']/2,z],[width+1,e['height']/2,z],[width*.3,e['height']/2,0]];classes=['outside']*5+['inside','outside','boundary'];result=row['result'];require(result['quality']=='native-re-evaluation-observation' and result['revision']==row['before']['capture']['solids']['revision'] and result['bodyId']==r['binding']['corners']['outputId'] and result['featureId']==r['binding']['corners']['featureId'] and result['engineRevision']==r['engineRevision'] and result['unit']=='millimeter','actual source/body/build query binding');require([x['point'] for x in result['points']]==points and [x['classification'] for x in result['points']]==classes,'independent physical material/void/cap points');observations.append({'label':row['label'],'effectiveWidthMm':width,'baseWidthExpression':model['definitions'][0]['expression'] if model else 'mm(100)','activeId':model['activeId'] if model else None,'nativeVolume':row['before']['capture']['solids']['bodies'][0]['metrics']['nativeVolume']})
        if row.get('kind')=='refusal':require(row['error'] and not row['error']['committed'] and not row['error']['possiblyCommitted'] and normalized(row['before'])==normalized(row['after']),'actual configuration refusal preserved durable source/journal/resources')
        if row.get('kind')=='review':
            a,b=row['before'],row['after'];require(material(a['manufacturing']['metadata'],r)==material(b['manufacturing']['metadata'],r) and a['manufacturing']['metadata']['revision']!=b['manufacturing']['metadata']['revision'],'genuine current review preserves semantic assignments');require(row['proposal']['objectCount']==row['proposal']['regionCount']==1 and row['result']['status']=='accepted','actual review receipt');require({k:v for k,v in a['capture']['native'].items() if k!='materialRevision'}=={k:v for k,v in b['capture']['native'].items() if k!='materialRevision'} and a['capture']['solids']['bodies']==b['capture']['solids']['bodies'],'metadata review changed only its intended material revision, not geometry/source/counters')
    inactive=one([x for x in r['rows'] if x.get('kind')=='inactive-base-edit'],'actual inactive Base edit');wa,ma,_=state(inactive['before'],r,mapping,object_ids);wb,mb,_=state(inactive['after'],r,mapping,object_ids);require(wa==wb==90 and ma==spec(100,90,'compact') and mb==spec(120,90,'compact') and inactive['before']['capture']['native']['source']==inactive['after']['capture']['native']['source'] and inactive['before']['capture']['solids']['bodies'][0]['metrics']==inactive['after']['capture']['solids']['bodies'][0]['metrics'],'Base intent can change while selected Compact geometry stays exact')
    required={'compact80':(80,spec(100,80,'compact')),'compact90':(90,spec(100,90,'compact')),'base120':(120,spec(120,90,None)),'compact90-reopened':(90,spec(120,90,'compact'))};require(len(r['saved'])==4 and {x['label'] for x in r['saved']}==set(required),'four finite native variants');saved={};assignment=None
    for row in r['saved']:
        width,model=required[row['label']];actual,stored,_=state(row['before'],r,mapping,object_ids);require(actual==row['width']==width and stored==row['spec']==model,'independent saved selected configuration meaning');raw=(folder/row['savedFile']).read_bytes();require(len(raw)==row['bytes'] and hashlib.sha256(raw).hexdigest()==row['sha256'],'actual browser/server/native bytes');native=json.loads(raw);require(native['format']=='codi-jsketcher-project' and native['version']==2 and native['unit']=='millimeter','native envelope2 distinct from physical source2');project=native['project'];before=row['before']['capture']['native'];require(project['model']['history']==before['history'] and project['model']['counters']==before['counters'] and project['model']['expressions']==before['expressions'],'exact authored graph/counters/variant source');require(len(project['sketches'])==1 and project['sketches'][0]['id']==r['binding']['faceId'] and project['sketches'][0]['data']==json.loads(before['source']),'exact actual solved source IDs/coordinates/equations');require(native['manufacturing']==row['before']['manufacturing']['metadata'],'real saved current material intent');identity=material(native['manufacturing'],r);assignment=identity if assignment is None else assignment;require(identity==assignment,'same reviewed identities across variants');require('nativeHandle' not in raw.decode() and 'candidateJSON' not in raw.decode(),'no runtime ownership/candidates persisted');saved[row['label']]={'sha256':row['sha256'],'metadataRevision':native['manufacturing']['revision'],'native':native,'width':width}
    a,b=saved['compact90'],saved['compact90-reopened'];require(a['native']['project']['sketches']==b['native']['project']['sketches'] and a['native']['project']['model']['expressions']!=b['native']['project']['model']['expressions'] and a['metadataRevision']!=b['metadataRevision'],'equal Compact geometry retains distinct edited Base/source/review revisions');runtime=[x for x in r['rows'] if x['label']=='Exact composed runtime'];require(len(runtime)==4,'initial and three fresh Open runtime bindings')
    for row in runtime:require({a['name']:a['sha256'] for a in row['assets']}==r['pins']['files'] and row['outer']['sha256']==r['pins']['outer']['sha256'],'exact runtime asset source pins')
    print(json.dumps({'status':'PASS_SCOPED_BASE_COMPACT','nativeFiles':{k:{n:v for n,v in value.items() if n!='native'} for k,value in saved.items()},'observations':observations,'limits':['Only Base/null and one sparse Compact variant of this selected rectangle/through-hole family.','Every configuration formula is validated; only selected Native geometry is evaluated.','No suppression, optimizer, copied per-variant geometry or general product-family automation qualification.']},indent=2))

if __name__=='__main__':main()
